CREATE TABLE file_uploads(id BIGINT PRIMARY KEY,campus_id BIGINT,owner_user_id BIGINT,access_domain VARCHAR(32),purpose VARCHAR(32),file_name VARCHAR(255),mime_type VARCHAR(128),size_bytes BIGINT,expected_sha256 CHAR(64),token_digest CHAR(64) UNIQUE,expires_at TIMESTAMP,state VARCHAR(32),object_key_encrypted VARBINARY(2048),original_sha256 CHAR(64),attachment_id BIGINT,created_at TIMESTAMP,updated_at TIMESTAMP);
CREATE TABLE file_attachments(id BIGINT PRIMARY KEY,upload_id BIGINT UNIQUE,campus_id BIGINT,owner_user_id BIGINT,access_domain VARCHAR(32),purpose VARCHAR(32),file_name VARCHAR(255),mime_type VARCHAR(128),size_bytes BIGINT,original_sha256 CHAR(64),content_sha256 CHAR(64),object_key_encrypted VARBINARY(2048),scan_status VARCHAR(32),state VARCHAR(32),created_at TIMESTAMP,updated_at TIMESTAMP);
ALTER TABLE async_jobs ADD COLUMN file_attachment_id BIGINT;
CREATE TABLE file_cleanup_jobs(id BIGINT PRIMARY KEY,object_key_encrypted VARBINARY(2048),upload_id BIGINT,attachment_id BIGINT,state VARCHAR(32),retry_count INT DEFAULT 0,next_retry_at TIMESTAMP,picked_at TIMESTAMP,claim_token VARCHAR(64),created_at TIMESTAMP,updated_at TIMESTAMP);
CREATE TABLE material_files(id BIGINT PRIMARY KEY,user_id BIGINT,campus_id BIGINT,object_key VARCHAR(512),object_key_encrypted VARBINARY(2048),current_attachment_id BIGINT,file_hash CHAR(64),size_bytes BIGINT,mime_type VARCHAR(128),file_name VARCHAR(255),expires_at TIMESTAMP,tags_json VARCHAR(4000),encrypted BOOLEAN,scan_status VARCHAR(32),status VARCHAR(32),version INT DEFAULT 0,created_at TIMESTAMP,updated_at TIMESTAMP,deleted_at TIMESTAMP);
CREATE TABLE material_versions(id BIGINT PRIMARY KEY,file_id BIGINT,version_no INT,object_key VARCHAR(512),object_key_encrypted VARBINARY(2048),attachment_id BIGINT,file_hash CHAR(64),created_at TIMESTAMP,UNIQUE(file_id,version_no));
CREATE TABLE material_checklist_items(id BIGINT PRIMARY KEY,material_version_id BIGINT);
CREATE TABLE material_usage_records(id BIGINT PRIMARY KEY,file_id BIGINT);
CREATE TABLE growth_records(id BIGINT PRIMARY KEY,proof_file_id BIGINT);
